/* ===== 62-ki-post-card ===== */
try {
/* ki-post-card – når posten kommer, i samme stil som resten av dashbordet.
 *
 * type: custom:ki-post-card
 * entity: sensor.nar_kommer_posten_posten_sensor_next
 * relativ: sensor.nar_kommer_posten_posten_sensor_next_relative
 * navn: Post
 * tekst: Post leveres
 * path: '#post'             # valgfritt: trykk navigerer hit
 * dager: [2, 4]             # valgfritt: ukedagene posten kommer (1 = mandag)
 * farge: '#8cbef5'          # sirkelens farge når leveringen er nær
 * pakker: true              # finn pakker fra Norwegian Parcel Tracker selv
 * pakker_leverte: false     # ta med ferdig leverte pakker
 */
const KI_POST_VERSJON = "3.1.0";

const KI_POST_STIL = `
  :host { display:block; max-width:100%; --myk:cubic-bezier(.2,.8,.2,1); }
  *, *::before, *::after { box-sizing:border-box; min-width:0; }

  /* Pilleform, som radene i dashbordet: rundt ikonfelt til venstre, to linjer tekst.
     Sirkelen er farget når leveringen er nær — nøytral ellers, slik en romflis er
     farget bare når rommet er aktivt. */
  .kort { display:flex; align-items:center; gap:14px; width:100%;
    border-radius:999px; background:var(--gray200); color:var(--gray1000);
    padding:8px 22px 8px 8px; cursor:pointer; border:0; font:inherit; text-align:left;
    transition:transform .12s var(--myk); }
  .kort:active { transform:scale(.995); }

  .ring { width:64px; height:64px; flex:none; border-radius:50%;
    display:flex; align-items:center; justify-content:center;
    background:rgba(250,251,252,.10); color:var(--gray1000);
    transition:background .5s var(--myk), color .4s; }
  .kort.nar .ring { background:var(--tone,#8cbef5); color:var(--black,#1b1b1b); }

  .ring svg { width:28px; height:28px; display:block; }
  /* Brevet hopper ned i kassa når posten kommer i dag */
  .kort.i_dag .brev { animation:kiPoSlipp 2.6s var(--myk) infinite; }
  @keyframes kiPoSlipp {
    0%, 60% { transform:translateY(0); opacity:1 }
    72% { transform:translateY(5px); opacity:.35 }
    84%, 100% { transform:translateY(0); opacity:1 }
  }

  .tekst { flex:1; min-width:0; display:grid; gap:2px; }
  .n { font-size:22px; font-weight:500; line-height:1.2;
    overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
  .u { font-size:16px; opacity:.55; overflow:hidden; text-overflow:ellipsis;
    white-space:nowrap; }

  /* Ukestripa: én prikk per ukedag, tent på dagene posten pleier å komme */
  .uke { display:flex; gap:5px; flex:none; }
  .uke i { width:26px; height:26px; border-radius:50%; display:flex;
    align-items:center; justify-content:center; font-size:10px; font-weight:700;
    font-style:normal; background:rgba(250,251,252,.09); opacity:.6; }
  .uke i.pa { background:var(--tone,#8cbef5); color:var(--black,#1b1b1b); opacity:1; }
  @media (max-width:520px) { .uke { display:none; } }

  /* Pakkene under postraden. Samme pilleform, men lavere: de er underordnet, og
     antallet varierer — står de like høye som postraden, tar fem pakker hele skjermen. */
  .pakker { display:grid; gap:6px; margin-top:6px; }
  .pakke { display:flex; align-items:center; gap:12px; width:100%; border:0; font:inherit;
    text-align:left; cursor:pointer; border-radius:999px; background:var(--gray200);
    color:var(--gray1000); padding:7px 18px 7px 7px;
    transition:transform .12s var(--myk); }
  .pakke:active { transform:scale(.995); }
  .pring { width:44px; height:44px; flex:none; border-radius:50%; display:flex;
    align-items:center; justify-content:center; --mdc-icon-size:21px;
    background:rgba(250,251,252,.10); }
  .pakke.klar .pring { background:var(--green,#5ad18b); color:var(--black,#1b1b1b); }
  .pakke.levert { opacity:.5; }
  .pakke.stuck .pring { background:var(--orange,#f0a952); color:var(--black,#1b1b1b); }
  .ptekst { flex:1; min-width:0; display:grid; gap:1px; }
  .pn { font-size:15px; font-weight:500; overflow:hidden; text-overflow:ellipsis;
    white-space:nowrap; }
  .pu { font-size:13px; opacity:.55; overflow:hidden; text-overflow:ellipsis;
    white-space:nowrap; }
  .pdag { font-size:12.5px; opacity:.45; flex:none; white-space:nowrap; }
  @media (max-width:380px) { .pdag { display:none; } }

  .tom { padding:16px 18px; border-radius:24px; background:var(--gray200);
    color:var(--gray1000); font-size:14px; opacity:.7; }
  @media (prefers-reduced-motion: reduce) { .kort, .brev { animation:none; transition:none; } }
`;


const kiPoEsc = (s) => String(s ?? "").replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
const KI_PO_MND = ["jan", "feb", "mar", "apr", "mai", "jun", "jul", "aug", "sep", "okt", "nov", "des"];

class KiPostCard extends HTMLElement {
  constructor() { super(); this.attachShadow({ mode: "open" }); }
  static getConfigElement() { return document.createElement("ki-post-card-editor"); }
  static getStubConfig() { return { entity: "sensor.nar_kommer_posten_posten_sensor_next" }; }
  getCardSize() { return 2; }
  getGridOptions() { return { columns: 12, rows: 2, min_rows: 2 }; }

  setConfig(c) {
    if (!c || !c.entity) throw new Error("Sett entity: til sensoren med neste leveringsdato");
    this._c = { navn: "Post", tekst: "Post leveres", ...c };
    this._forrige = null;
  }
  /* Skjules når lanseringskortet står på serier, filmer eller kalender */
  _visningslytter() {
    if (this._visAv) return;
    this._visAv = (e) => {
      const v = (e && e.detail && e.detail.visning) || "alle";
      const skjul = [].concat(this._c && this._c.skjul_paa !== undefined
        ? this._c.skjul_paa : ["serie", "film", "kalender"]);
      this.style.display = skjul.includes(v) ? "none" : "";
    };
    window.addEventListener("ki-lansering-visning", this._visAv);
  }
  connectedCallback() { this._visningslytter(); }
  disconnectedCallback() {
    if (this._visAv) { window.removeEventListener("ki-lansering-visning", this._visAv); this._visAv = null; }
  }

  set hass(h) {
    const g = this._h; this._h = h; if (!this._c) return;
    const ids = [this._c.entity, this._c.relativ].filter(Boolean);
    if (!g || ids.some((id) => g.states[id] !== h.states[id])) this._tegn();
  }

  _trykk() {
    const c = this._c;
    if (c.path) {
      history.pushState(null, "", c.path);
      window.dispatchEvent(new Event("location-changed"));
      window.dispatchEvent(new HashChangeEvent("hashchange"));
      return;
    }
    this.dispatchEvent(new CustomEvent("hass-more-info", { detail: { entityId: c.entity }, bubbles: true, composed: true }));
  }

  /* Pakker fra Norwegian Parcel Tracker, funnet selv.
   *
   * Integrasjonen lager én enhet per pakke, med `..._status` som hovedsensor og resten
   * som attributter og søskensensorer. Vi finner statussensorene gjennom
   * entitetsregisteret, så ingenting må listes opp i YAML-en — pakker kommer og går, og
   * en liste man må vedlikeholde ville vært utdatert før den var skrevet.
   *
   * Vi grupperer per enhet (`device_id`) når registeret har det, ellers per
   * entitetsnavn. Det er enheten som er «én pakke».
   */
  _pakker() {
    const h = this._h;
    if (!h || this._c.pakker === false) return [];
    const reg = h.entities || {};
    const ut = [];

    for (const [id, e] of Object.entries(reg)) {
      if (e.platform !== "norwegian_parcel_tracker") continue;
      if (!id.startsWith("sensor.") || !/_status$/.test(id)) continue;
      const st = h.states[id];
      if (!st) continue;
      const a = st.attributes || {};

      /* Navnet: integrasjonen setter visningsnavn per pakke. Faller vi tilbake til
         entitets-ID-en, får vi sporingsnummeret, som er bedre enn ingenting. */
      const navn = (a.friendly_name || id.slice(7))
        .replace(/\s*status\s*$/i, "").trim() || "Pakke";

      const tilstand = String(st.state || "").toLowerCase();
      const levert = /levert|delivered|utlevert/.test(tilstand);
      const klar = /hentes|ready|klar|pickup|utleveringssted/.test(tilstand) && !levert;
      const stuck = !!a.stale || !!a.stuck;

      ut.push({ id, navn, tilstand: st.state, levert, klar, stuck,
        hentested: a.pickup_point || a.hentested || "",
        levering: a.estimated_delivery || a.forventet_levering || "",
        siste: a.latest_event || a.siste_hendelse || "" });
    }

    const vis = this._c.pakker_leverte ? ut : ut.filter((p) => !p.levert);
    /* Rekkefølgen er den man vil handle på: klar til henting først, så fastlåste,
       så resten. En pakke som venter på deg er det eneste som haster. */
    const rang = (p) => (p.klar ? 0 : p.stuck ? 1 : p.levert ? 3 : 2);
    return vis.sort((a2, b) => rang(a2) - rang(b) || a2.navn.localeCompare(b.navn, "nb"));
  }

  _pakkerHtml() {
    const pakker = this._pakker();
    if (!pakker.length) return "";
    const dato = (iso) => {
      if (!iso) return "";
      const d = new Date(iso);
      if (isNaN(d)) return "";
      const naa = new Date(); naa.setHours(0, 0, 0, 0);
      const diff = Math.round((new Date(d).setHours(0, 0, 0, 0) - naa) / 86400000);
      if (diff === 0) return "i dag";
      if (diff === 1) return "i morgen";
      if (diff > 1 && diff < 7) return d.toLocaleDateString("nb-NO", { weekday: "long" });
      return d.toLocaleDateString("nb-NO", { day: "numeric", month: "short" });
    };
    return `<div class="pakker">${pakker.map((p) => {
      const under = p.klar && p.hentested ? `Klar på ${p.hentested}`
        : p.siste || p.tilstand;
      return `<button class="pakke ${p.klar ? "klar" : ""} ${p.stuck ? "stuck" : ""}
          ${p.levert ? "levert" : ""}" data-pakke="${kiPoEsc(p.id)}">
        <span class="pring"><ha-icon icon="${p.klar ? "mdi:package-variant-closed-check"
          : p.levert ? "mdi:check" : p.stuck ? "mdi:alert-outline" : "mdi:package-variant"}"></ha-icon></span>
        <span class="ptekst">
          <span class="pn">${kiPoEsc(p.navn)}</span>
          <span class="pu">${kiPoEsc(under)}</span>
        </span>
        <span class="pdag">${kiPoEsc(dato(p.levering))}</span>
      </button>`;
    }).join("")}</div>`;
  }

  _tegn() {
    const c = this._c, h = this._h; if (!c || !h) return;
    const st = h.states[c.entity];
    const d = st ? new Date(st.state) : null;
    if (!st || !d || isNaN(d)) {
      const tom = `<style>${KI_POST_STIL}</style><div class="tom">Fant ingen leveringsdato.</div>`;
      if (tom !== this._forrige) { this.shadowRoot.innerHTML = tom; this._forrige = tom; }
      return;
    }
    const nå = new Date(); nå.setHours(0, 0, 0, 0);
    const dag = new Date(d); dag.setHours(0, 0, 0, 0);
    const diff = Math.round((dag - nå) / 86400000);
    const rel = c.relativ && h.states[c.relativ] ? h.states[c.relativ].state : "";
    const ukedag = d.toLocaleDateString("nb-NO", { weekday: "long" });
    /* Tittelen er når, underteksten hva. «I morgen» er det man leser først; at det er
       posten, står under — som «Låst» over «Dørlås» i dashbordet. */
    const nar = diff === 0 ? "I dag" : diff === 1 ? "I morgen"
      : diff <= 6 ? `På ${ukedag}` : `${d.getDate()}. ${KI_PO_MND[d.getMonth()]}`;
    const under = diff <= 1 ? (c.tekst || "Post leveres")
      : `${c.tekst || "Post leveres"} · ${rel || `om ${diff} dager`}`;

    /* Ukestripa tennes bare når den vet noe: `dager: [2, 4]` er ukedagene posten
       kommer, der 1 er mandag. Uten den vises ingen stripe — en gjettet stripe er
       verre enn ingen. */
    const uke = Array.isArray(c.dager) && c.dager.length ? c.dager.map(Number) : null;
    const UKE = ["ma", "ti", "on", "to", "fr", "lø", "sø"];

    const html = `<style>${KI_POST_STIL}</style>
      <button class="kort ${diff === 0 ? "i_dag" : ""} ${diff <= 1 ? "nar" : ""}"
        style="--tone:${kiPoEsc(c.farge || "#8cbef5")}">
        <span class="ring">
          <svg viewBox="0 0 64 64" fill="none" stroke="currentColor" stroke-width="3.6"
               stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
            <path d="M12 30a10 10 0 0 1 20 0v16H12z" fill="currentColor" fill-opacity=".16"/>
            <path d="M32 46h20V30a10 10 0 0 0-10-10H22"/>
            <path d="M18 46v9"/>
            <path d="M50 28V16h8v7h-8"/>
            <g class="brev">
              <rect x="24" y="29" width="16" height="11" rx="2" fill="currentColor"
                    fill-opacity=".95" stroke="none"/>
              <path d="M24 30l8 6 8-6" stroke="var(--gray200)" stroke-width="2"/>
            </g>
          </svg>
        </span>
        <span class="tekst">
          <span class="n">${kiPoEsc(nar)}</span>
          <span class="u">${kiPoEsc(under)}</span>
        </span>
        ${uke ? `<span class="uke">${UKE.map((u, i) =>
          `<i class="${uke.includes(i + 1) ? "pa" : ""}">${u}</i>`).join("")}</span>` : ""}
      </button>
      ${this._pakkerHtml()}`;
    if (html === this._forrige) return;
    this.shadowRoot.innerHTML = html; this._forrige = html;
    this.shadowRoot.querySelector(".kort").addEventListener("click", () => this._trykk());
    for (const el of this.shadowRoot.querySelectorAll("[data-pakke]")) {
      el.addEventListener("click", () => this.dispatchEvent(new CustomEvent("hass-more-info",
        { detail: { entityId: el.dataset.pakke }, bubbles: true, composed: true })));
    }
  }
}
if (!customElements.get("ki-post-card")) window.KI.define("ki-post-card", KiPostCard);

class KiPostCardEditor extends HTMLElement {
  setConfig(c) { this._c = c; this._r(); }
  set hass(h) { this._h = h; this._r(); }
  _r() {
    if (!this._h || !this._c) return;
    if (!this._f) {
      this._f = document.createElement("ha-form");
      const n = { entity: "Dato-sensor", relativ: "Relativ tekst (valgfri)", tekst: "Tekst", navn: "Navn", path: "Trykk går til" };
      this._f.computeLabel = (s) => n[s.name] || s.name;
      this._f.addEventListener("value-changed", (e) => this.dispatchEvent(new CustomEvent("config-changed",
        { detail: { config: e.detail.value }, bubbles: true, composed: true })));
      this.appendChild(this._f);
    }
    this._f.hass = this._h; this._f.data = this._c;
    this._f.schema = [
      { name: "entity", selector: { entity: { domain: "sensor" } } },
      { name: "relativ", selector: { entity: { domain: "sensor" } } },
      { name: "tekst", selector: { text: {} } },
      { name: "path", selector: { text: {} } },
    ];
  }
}
if (!customElements.get("ki-post-card-editor")) window.KI.define("ki-post-card-editor", KiPostCardEditor);

window.customCards = window.customCards || [];
if (!window.customCards.some((k) => k.type === "ki-post-card")) window.customCards.push({ type: "ki-post-card", name: "KI Post", description: "Når posten kommer", preview: true });
} catch (e) { console.error("ki-cards: 62-ki-post-card feilet", e); }

/* ===== 63-ki-bursdag-pro-card ===== */
try {
/* ki-bursdag-pro-card – bursdager i samme stil som kalenderkortene.
 * Leser de samme sensorene som ki-bursdag-card, men med nytt design:
 * stor dato til venstre, navn og alder til høyre, og lilla kort på selve dagen.
 *
 * type: custom:ki-bursdag-pro-card
 * kalender: calendar.birthdays      # bursdagene ligger som heldagshendelser
 * entities: [sensor.bursdag_rune]   # eller sensorer, som før
 * regex: birthday|bursdag           # eller finn sensorene selv
 * antall: 3
 * dager: 365            # hvor langt fram vi ser
 * legg_til: true        # knapp for å legge inn en ny bursdag
 * aar_fram: 10          # hvor mange år fram nye bursdager opprettes
 *
 * Fødselsåret leses fra hendelsen: skriv datoen i beskrivelsen («1985-04-12»,
 * «f. 1985» eller «født 1985»), eller sett den i tittelen: «Rune (1985)».
 */
const KI_BDP_VERSJON = "3.1.0";

/* Ett kakeikon, brukt både i flisa og i pillene. Sto det to steder, ville de kommet ut
   av takt ved første endring. */
const KI_BD_KAKE = `<svg viewBox="0 0 64 64" fill="none" stroke="currentColor"
  stroke-width="3.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
  <path d="M12 52V38a6 6 0 0 1 6-6h28a6 6 0 0 1 6 6v14z" fill="currentColor" fill-opacity=".16"/>
  <path d="M10 52h44M32 32V22"/>
  <g class="flamme"><path d="M32 20c3-3 1-6 0-7-1 1-3 4 0 7z" fill="currentColor"/></g>
  <path d="M20 32v-8M44 32v-8" opacity=".5"/>
</svg>`;

const KI_BDP_STIL = `
  :host { display:block; max-width:100%; --myk:cubic-bezier(.2,.8,.2,1); }
  *, *::before, *::after { box-sizing:border-box; min-width:0; }
  .rot { display:grid; gap:8px; color:var(--gray1000); }
  button { font:inherit; color:inherit; border:0; text-align:left; cursor:pointer; }

  /* --- den nærmeste: høy flis, som et rom --- */
  .flis { position:relative; display:grid; align-content:start;
    grid-template-columns:1fr auto; gap:0 12px;
    min-height:190px; padding:20px 22px 22px; border-radius:28px;
    background:var(--gray200); overflow:hidden;
    transition:transform .12s var(--myk), background .5s var(--myk); }
  .flis:active { transform:scale(.99); }
  .flis.i_dag { background:color-mix(in srgb, var(--tone) 24%, var(--gray200)); }

  .fnavn { grid-column:1; font-size:23px; font-weight:500; align-self:start;
    overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
  .fsirkel { grid-column:2; grid-row:1 / span 2; width:66px; height:66px; flex:none;
    border-radius:50%; display:flex; align-items:center; justify-content:center;
    background:rgba(250,251,252,.09); color:var(--gray1000);
    transition:background .5s var(--myk), color .4s; }
  .fsirkel svg { width:32px; height:32px; }
  .fsirkel.nar { background:var(--tone); color:var(--black,#1b1b1b); }

  /* Tallet er stort og lett, halen dempet ved siden av — som «23°» med «48%» */
  .fverdi { grid-column:1; display:flex; align-items:baseline; gap:10px;
    margin-top:34px; }
  .fverdi b { font-size:clamp(46px,13vw,64px); font-weight:200; line-height:1;
    letter-spacing:-.03em; font-variant-numeric:tabular-nums; }
  .fverdi i { font-style:normal; font-size:21px; font-weight:300; opacity:.5; }
  .funder { grid-column:1 / -1; font-size:14px; opacity:.55; margin-top:10px;
    overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }

  .fstripe { position:absolute; left:0; right:0; bottom:0; height:4px;
    background:rgba(128,128,128,.2); }
  .fstripe i { display:block; height:100%; background:var(--tone);
    transition:width .8s var(--myk); }

  /* --- de neste: piller med rundt ikon og to linjer --- */
  .pille { display:flex; align-items:center; gap:14px; width:100%;
    border-radius:999px; background:var(--gray200); padding:8px 20px 8px 8px;
    transition:transform .12s var(--myk); }
  .pille:active { transform:scale(.995); }
  .pikon { width:58px; height:58px; flex:none; border-radius:50%;
    display:flex; align-items:center; justify-content:center;
    background:rgba(250,251,252,.09); color:var(--gray1000);
    transition:background .5s var(--myk), color .4s; }
  .pikon svg { width:26px; height:26px; }
  .pille.nar .pikon { background:var(--tone); color:var(--black,#1b1b1b); }
  .pille.i_dag { background:color-mix(in srgb, var(--tone) 22%, var(--gray200)); }
  .ptekst { flex:1; min-width:0; display:grid; gap:1px; }
  .pn { font-size:19px; font-weight:500; overflow:hidden; text-overflow:ellipsis;
    white-space:nowrap; }
  .pu { font-size:14px; opacity:.55; overflow:hidden; text-overflow:ellipsis;
    white-space:nowrap; }
  .pdato { font-size:13px; opacity:.4; flex:none; white-space:nowrap; }
  @media (max-width:400px) { .pdato { display:none; } }

  /* Flammen blafrer bare på selve dagen — ellers ville tre kort blinket samtidig */
  .flamme { transform-box:fill-box; transform-origin:50% 100%; }
  .flis.i_dag .flamme, .pille.i_dag .flamme {
    animation:kiBdFlamme 1.6s ease-in-out infinite alternate; }
  @keyframes kiBdFlamme {
    from { transform:scale(.85) rotate(-6deg); opacity:.75 }
    to { transform:scale(1.1) rotate(6deg); opacity:1 }
  }

  .avkryss { display:flex; align-items:center; gap:10px; font-size:14px; opacity:.8;
    padding:2px 0 2px 2px; cursor:pointer; }
  .avkryss input { width:18px; height:18px; accent-color:var(--active-big,#ee95ff); }
  .skjemafeil { font-size:13px; color:var(--red,#e5706b); margin:2px 0 0; }

  .nyknapp { display:flex; align-items:center; justify-content:center; gap:8px;
    padding:13px; border-radius:999px; background:var(--gray200); opacity:.75;
    font-size:14px; --mdc-icon-size:19px; }
  .tom { padding:16px 18px; border-radius:24px; background:var(--gray200);
    font-size:14px; opacity:.7; }
  @media (prefers-reduced-motion: reduce) {
    .flis, .pille, .flamme, .fstripe i { animation:none; transition:none; }
  }
`;

/* «Rune (1985)», «Rune's Birthday» og «bursdag_rune» blir alle til «Rune» */
const kiBdNavn = (s) => String(s || "")
  .replace(/\(\s*\d{4}\s*\)/g, "")
  .replace(/[_-]+/g, " ")
  .replace(/\b(bursdag|birthday|fodselsdag|fødselsdag)\b/gi, "")
  .replace(/[’']\s*s\b/gi, "")
  .replace(/^\s*s\b/i, "")
  .replace(/\s{2,}/g, " ")
  .replace(/^[\s.,·-]+|[\s.,·-]+$/g, "")
  .replace(/^./, (c) => c.toUpperCase());

const kiBdEsc = (s) => String(s ?? "").replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
const KI_BD_MND = ["jan", "feb", "mar", "apr", "mai", "jun", "jul", "aug", "sep", "okt", "nov", "des"];

class KiBursdagProCard extends HTMLElement {
  constructor() { super(); this.attachShadow({ mode: "open" }); }
  static getConfigElement() { return document.createElement("ki-bursdag-pro-card-editor"); }
  static getStubConfig() { return { antall: 3 }; }
  getCardSize() { return 4; }

  setConfig(c) {
    this._c = { antall: 3, dager: 365, regex: "birthday|bursdag", legg_til: true, aar_fram: 10, ...(c || {}) };
    this._forrige = null; this._fraKalender = null; this._nytt = null;
  }

  /* Bursdagene som heldagshendelser i en kalender. Fødselsåret hentes fra
     beskrivelsen («1985-04-12», «f. 1985») eller fra tittelen («Rune (1985)»). */
  async _hentKalender() {
    const h = this._h, c = this._c; if (!h || !c.kalender) return;
    const fra = new Date(); fra.setHours(0, 0, 0, 0);
    const til = new Date(fra); til.setDate(til.getDate() + Number(c.dager || 365));
    try {
      const svar = await h.callApi("GET",
        `calendars/${c.kalender}?start=${encodeURIComponent(fra.toISOString())}&end=${encodeURIComponent(til.toISOString())}`);
      const nå = new Date(); nå.setHours(0, 0, 0, 0);
      const ut = [];
      (svar || []).forEach((e) => {
        const start = e.start && (e.start.date || e.start.dateTime || e.start);
        const d = new Date(start); if (isNaN(d)) return;
        d.setHours(0, 0, 0, 0);
        const tekst = `${e.description || ""} ${e.summary || ""}`;
        const full = tekst.match(/(\d{4})-(\d{2})-(\d{2})/);
        const bare = tekst.match(/(?:f\.?|født|fodt|\()\s*(\d{4})/i);
        const fodselsaar = full ? Number(full[1]) : bare ? Number(bare[1]) : null;
        ut.push({
          id: c.kalender, navn: kiBdNavn(e.summary || ""), dato: d,
          dager: Math.round((d - nå) / 86400000),
          alder: fodselsaar ? d.getFullYear() - fodselsaar : null,
          fodt: full ? full[0] : fodselsaar ? String(fodselsaar) : null,
          fra_kalender: true,
        });
      });
      ut.sort((a, b) => a.dager - b.dager);
      this._fraKalender = ut; this._forrige = null; this._tegn();
    } catch (feil) { this._fraKalender = []; }
  }
  /* Skjules når lanseringskortet står på serier, filmer eller kalender */
  _visningslytter() {
    if (this._visAv) return;
    this._visAv = (e) => {
      const v = (e && e.detail && e.detail.visning) || "alle";
      const skjul = [].concat(this._c && this._c.skjul_paa !== undefined
        ? this._c.skjul_paa : ["serie", "film", "kalender"]);
      this.style.display = skjul.includes(v) ? "none" : "";
    };
    window.addEventListener("ki-lansering-visning", this._visAv);
  }
  connectedCallback() {
    this._visningslytter();
    clearInterval(this._i);
    if (this._c && this._c.kalender) {
      this._i = setInterval(() => this._hentKalender(), 900000);
      if (this._h && this._fraKalender === null) this._hentKalender();
    }
  }
  disconnectedCallback() {
    clearInterval(this._i);
    if (this._visAv) { window.removeEventListener("ki-lansering-visning", this._visAv); this._visAv = null; }
  }

  set hass(h) {
    const g = this._h; this._h = h; if (!this._c) return;
    if (!g && this._c.kalender) this._hentKalender();
    if (!g || this._endret(g, h)) this._tegn();
  }
  _endret(g, h) {
    return this._ider().some((id) => g.states[id] !== h.states[id])
      || (this._c.kalender && g.states[this._c.kalender] !== h.states[this._c.kalender]);
  }

  _ider() {
    const c = this._c, h = this._h; if (!h) return [];
    if (c.entities && c.entities.length) return c.entities.map((e) => (typeof e === "string" ? e : e.entity));
    const re = new RegExp(c.regex, "i");
    return Object.keys(h.states).filter((id) => id.startsWith("sensor.") && re.test(id));
  }

  /* Tåler flere sensorformater: dato i state, eller i attributtene */
  _personer() {
    if (this._c.kalender) return (this._fraKalender || []).slice(0, Number(this._c.antall || 3));
    const h = this._h, nå = new Date(); nå.setHours(0, 0, 0, 0);
    const ut = [];
    this._ider().forEach((id) => {
      const st = h.states[id]; if (!st) return;
      const a = st.attributes || {};
      const rått = a.friendly_name_short || a.nickname || a.name || a.friendly_name || id.split(".").pop();
      const navn = kiBdNavn(rått);
      const rå = a.next_birthday || a.next_date || a.date_of_next_birthday || a.birthday || a.date || st.state;
      const d = new Date(rå);
      if (isNaN(d)) return;
      const neste = new Date(d); neste.setHours(0, 0, 0, 0);
      if (neste < nå && a.years_old === undefined) {
        neste.setFullYear(nå.getFullYear());
        if (neste < nå) neste.setFullYear(nå.getFullYear() + 1);
      }
      const dager = Math.round((neste - nå) / 86400000);
      if (dager < 0 || dager > Number(this._c.dager || 365)) return;
      const alder = a.years_old !== undefined ? Number(a.years_old) + (dager === 0 ? 0 : 1)
        : a.age !== undefined ? Number(a.age) : (a.birth_year ? neste.getFullYear() - Number(a.birth_year) : null);
      ut.push({ id, navn, dato: neste, dager, alder });
    });
    return ut.sort((a, b) => a.dager - b.dager).slice(0, Number(this._c.antall || 3));
  }

  /* Navn fra husets personer, så man slipper å skrive dem inn.
     Det er også den vanligste feilkilden: «Cybele» og «cybele» blir to oppføringer. */
  _personNavn() {
    const ut = [];
    for (const id of Object.keys((this._h && this._h.states) || {})) {
      if (!id.startsWith("person.")) continue;
      const n = (this._h.states[id].attributes || {}).friendly_name;
      if (n) ut.push(n);
    }
    return ut.sort((a, b) => a.localeCompare(b, "nb"));
  }

  /* Skjema for å legge inn en ny bursdag i kalenderen.
   *
   * Endret fra å lage én oppføring per år: nå lages ÉN hendelse som gjentas årlig.
   * Ti kopier i kalenderen var både rotete å rette i og noe som gikk tomt etter ti år,
   * uten at noen fikk beskjed. En gjentakelse går aldri ut.
   *
   * Årstallet skrives for seg. En `type="date"` krever at man blar til 1985 i en
   * månedsvelger, og det er tungt på mobil — de fleste vet årstallet og skriver det
   * raskere enn de blar til det.
   */
  _skjema() {
    const d = this._nytt || {};
    const personer = this._personNavn();
    const iAar = new Date().getFullYear();
    const gjentas = d.gjentas !== false;
    return `<div class="skjema">
      <div><label>Navn</label>
        <input type="text" data-f="navn" list="ki-bd-personer" autocomplete="off"
               value="${kiBdEsc(d.navn || "")}" placeholder="Rune">
        ${personer.length ? `<datalist id="ki-bd-personer">${
          personer.map((n) => `<option value="${kiBdEsc(n)}"></option>`).join("")}</datalist>` : ""}
      </div>
      <div class="skjemarad">
        <div><label>Dag og måned</label>
          <input type="text" data-f="dagmnd" inputmode="numeric" autocomplete="off"
                 value="${kiBdEsc(d.dagmnd || "")}" placeholder="12.04"></div>
        <div><label>Fødselsår</label>
          <input type="number" min="1900" max="${iAar}" data-f="fodtaar" inputmode="numeric"
                 value="${kiBdEsc(d.fodtaar || "")}" placeholder="1985"></div>
      </div>
      <label class="avkryss">
        <input type="checkbox" data-f="gjentas" ${gjentas ? "checked" : ""}>
        <span>Gjentas hvert år</span>
      </label>
      <p class="hint">${gjentas
        ? "Én oppføring som gjentas årlig. Fødselsåret lagres i beskrivelsen, slik at alderen kan regnes ut."
        : `Lager ${this._c.aar_fram || 10} separate oppføringer, én per år.`}</p>
      ${this._feil ? `<p class="skjemafeil">${kiBdEsc(this._feil)}</p>` : ""}
      <div class="sknapper">
        <button class="sk" data-s="avbryt">Avbryt</button>
        <button class="sk lagre" data-s="lagre">Legg til</button>
      </div>
    </div>`;
  }

  /* «12.04», «12/4», «12 4» eller «1204» → {dag, mnd}. Null når det ikke gir mening.
     Folk skriver datoer på mange måter, og å avvise alle utenom én er unødig strengt. */
  _tolkDagMnd(tekst) {
    const t = String(tekst || "").trim();
    let m = t.match(/^(\d{1,2})\s*[.\/-]\s*(\d{1,2})\.?$/);
    if (!m && /^\d{4}$/.test(t)) m = [null, t.slice(0, 2), t.slice(2)];
    if (!m) return null;
    const dag = Number(m[1]), mnd = Number(m[2]);
    if (dag < 1 || dag > 31 || mnd < 1 || mnd > 12) return null;
    // 31. februar finnes ikke: la Date avgjøre om dagen er ekte i måneden
    const prove = new Date(2024, mnd - 1, dag);   // skuddår, så 29.02 godtas
    if (prove.getMonth() !== mnd - 1 || prove.getDate() !== dag) return null;
    return { dag, mnd };
  }

  async _lagre() {
    const d = this._nytt || {}, c = this._c, h = this._h;
    const dm = this._tolkDagMnd(d.dagmnd);
    const fodtAar = Number(d.fodtaar);
    if (!d.navn || !dm || !c.kalender) {
      this._feil = !d.navn ? "Skriv et navn."
        : !dm ? "Skriv dag og måned, som 12.04."
        : "Ingen kalender er valgt i kortet.";
      this._forrige = null; return this._tegn();
    }
    this._feil = null;

    const harAar = Number.isFinite(fodtAar) && fodtAar >= 1900 && fodtAar <= new Date().getFullYear();
    const iso = (x) => `${x.getFullYear()}-${String(x.getMonth() + 1).padStart(2, "0")}-${String(x.getDate()).padStart(2, "0")}`;
    const tittel = harAar ? `${d.navn} (${fodtAar})` : d.navn;
    const beskrivelse = harAar ? `Født ${fodtAar}-${String(dm.mnd).padStart(2, "0")}-${String(dm.dag).padStart(2, "0")}` : "";

    /* Første forekomst: i år hvis datoen ikke er passert, ellers neste år. Legger vi
       den i fortiden, dukker bursdagen opp som «passert» med en gang. */
    const naa = new Date(); naa.setHours(0, 0, 0, 0);
    let aar = naa.getFullYear();
    if (new Date(aar, dm.mnd - 1, dm.dag) < naa) aar += 1;
    if (harAar && fodtAar > aar) aar = fodtAar;

    const lag = async (a2, rrule) => {
      const dag = new Date(a2, dm.mnd - 1, dm.dag);
      const slutt = new Date(dag); slutt.setDate(slutt.getDate() + 1);
      const data = { entity_id: c.kalender, summary: tittel,
        start_date: iso(dag), end_date: iso(slutt) };
      if (beskrivelse) data.description = beskrivelse;
      if (rrule) data.rrule = rrule;
      await h.callService("calendar", "create_event", data);
    };

    if (d.gjentas !== false) {
      /* Én hendelse som gjentas årlig. Støtter ikke kalenderen rrule, faller vi
         tilbake til kopier — bedre enn å feile stille og ikke lagre noe. */
      try {
        await lag(aar, "FREQ=YEARLY");
      } catch (e) {
        this._feil = "Kalenderen støtter ikke årlig gjentakelse — la inn kopier i stedet.";
        const n = Math.max(1, Math.min(30, Number(c.aar_fram || 10)));
        for (let i = 0; i < n; i++) {
          /* eslint-disable no-await-in-loop */
          await lag(aar + i);
        }
      }
    } else {
      const n = Math.max(1, Math.min(30, Number(c.aar_fram || 10)));
      for (let i = 0; i < n; i++) {
        /* eslint-disable no-await-in-loop */
        await lag(aar + i);
      }
    }

    this._nytt = null; this._forrige = null;
    await this._hentKalender();
    this._tegn();
  }

  _tegn() {
    const c = this._c, h = this._h; if (!c || !h) return;
    if (this._nytt) {
      const html = `<style>${KI_BDP_STIL}</style><div class="rot">${this._skjema()}</div>`;
      if (html !== this._forrige) {
        this.shadowRoot.innerHTML = html; this._forrige = html;
        const r = this.shadowRoot;
        r.querySelectorAll("[data-f]").forEach((el) => el.addEventListener("change", () => {
          this._nytt[el.dataset.f] = el.type === "checkbox" ? el.checked : el.value;
        }));
        r.querySelectorAll("[data-s]").forEach((b) => b.addEventListener("click", () => {
          if (b.dataset.s === "avbryt") { this._nytt = null; this._forrige = null; return this._tegn(); }
          const felt = r.querySelectorAll("[data-f]");
          felt.forEach((el) => { this._nytt[el.dataset.f] = el.value; });
          this._lagre();
        }));
      }
      return;
    }
    const folk = this._personer();
    const farger = ["var(--active-big,#ee95ff)", "var(--blue)", "var(--yellow)", "var(--green)", "var(--orange)"];
    /* Første bursdag er en høy flis: navnet oppe til venstre, kakesirkelen i motsatt
       hjørne, og det store tallet nede — samme oppbygning som romflisene. De neste blir
       piller, siden de sjelden haster.
       Sirkelen er farget bare når det nærmer seg. Ellers er den nøytral, slik et rom
       som er av ikke lyser. */
    const kort = (p, i) => {
      const ukedag = p.dato.toLocaleDateString("nb-NO", { weekday: "long" });
      const under = p.alder ? `fyller ${p.alder} år` : "bursdag";
      const dato = `${p.dato.getDate()}. ${KI_BD_MND[p.dato.getMonth()]}`;
      const tone = farger[i % farger.length];
      const nar = p.dager <= 14;

      if (i) {
        const naar = p.dager === 0 ? "I dag" : p.dager === 1 ? "I morgen"
          : `${p.dager} dager`;
        return `<button class="pille ${p.dager === 0 ? "i_dag" : ""} ${nar ? "nar" : ""}"
            data-e="${kiBdEsc(p.id)}" style="--tone:${tone}">
          <span class="pikon">${KI_BD_KAKE}</span>
          <span class="ptekst">
            <span class="pn">${kiBdEsc(p.navn)}</span>
            <span class="pu">${kiBdEsc(naar)} · ${kiBdEsc(under)}</span>
          </span>
          <span class="pdato">${kiBdEsc(dato)}</span>
        </button>`;
      }

      /* Tallet er det store: dagene igjen, eller «I dag» på selve dagen. */
      const stort = p.dager === 0 ? "I dag" : String(p.dager);
      const halet = p.dager === 0 ? "" : p.dager === 1 ? "dag" : "dager";
      /* Stripa under fylles jo nærmere vi kommer, med 60 dager som helt vindu. */
      const fyll = Math.max(0, Math.min(100, (1 - Math.min(p.dager, 60) / 60) * 100));
      return `<button class="flis ${p.dager === 0 ? "i_dag" : ""}"
          data-e="${kiBdEsc(p.id)}" style="--tone:${tone}">
        <span class="fnavn">${kiBdEsc(p.navn)}</span>
        <span class="fsirkel ${nar ? "nar" : ""}">${KI_BD_KAKE}</span>
        <span class="fverdi">
          <b>${kiBdEsc(stort)}</b>${halet ? `<i>${halet}</i>` : ""}
        </span>
        <span class="funder">${kiBdEsc(under)} · ${kiBdEsc(ukedag)} ${kiBdEsc(dato)}</span>
        <span class="fstripe"><i style="width:${fyll.toFixed(0)}%"></i></span>
      </button>`;
    };

    const nyKnapp = c.kalender && c.legg_til !== false
      ? `<button class="nyknapp" data-ny="1"><ha-icon icon="mdi:plus"></ha-icon>Ny bursdag</button>` : "";
    const html = `<style>${KI_BDP_STIL}</style><div class="rot">${
      folk.length ? folk.map(kort).join("") : `<div class="tom">Ingen bursdager framover.</div>`}${nyKnapp}</div>`;
    if (html === this._forrige) return;
    this.shadowRoot.innerHTML = html; this._forrige = html;
    this.shadowRoot.querySelectorAll("[data-e]").forEach((el) => el.addEventListener("click", () =>
      this.dispatchEvent(new CustomEvent("hass-more-info", { detail: { entityId: el.dataset.e }, bubbles: true, composed: true }))));
    const ny = this.shadowRoot.querySelector("[data-ny]");
    if (ny) ny.addEventListener("click", () => { this._nytt = { aar: c.aar_fram || 10 }; this._forrige = null; this._tegn(); });
  }
}
if (!customElements.get("ki-bursdag-pro-card")) window.KI.define("ki-bursdag-pro-card", KiBursdagProCard);

class KiBursdagProCardEditor extends HTMLElement {
  setConfig(c) { this._c = c; this._r(); }
  set hass(h) { this._h = h; this._r(); }
  _r() {
    if (!this._h || !this._c) return;
    if (!this._f) {
      this._f = document.createElement("ha-form");
      const n = { kalender: "Bursdagskalender", antall: "Antall kort", dager: "Dager framover",
        regex: "Finn sensorer med (regex)", legg_til: "Knapp for ny bursdag", aar_fram: "År fram nye lages" };
      this._f.computeLabel = (s) => n[s.name] || s.name;
      this._f.addEventListener("value-changed", (e) => this.dispatchEvent(new CustomEvent("config-changed",
        { detail: { config: e.detail.value }, bubbles: true, composed: true })));
      this.appendChild(this._f);
    }
    this._f.hass = this._h; this._f.data = this._c;
    this._f.schema = [
      { name: "kalender", selector: { entity: { domain: "calendar" } } },
      { name: "antall", selector: { number: { mode: "box", min: 1, max: 10 } } },
      { name: "legg_til", selector: { boolean: {} } },
      { name: "aar_fram", selector: { number: { mode: "box", min: 1, max: 30 } } },
      { name: "dager", selector: { number: { mode: "box", min: 1, max: 400 } } },
      { name: "regex", selector: { text: {} } },
    ];
  }
}
if (!customElements.get("ki-bursdag-pro-card-editor")) window.KI.define("ki-bursdag-pro-card-editor", KiBursdagProCardEditor);

window.customCards = window.customCards || [];
if (!window.customCards.some((k) => k.type === "ki-bursdag-pro-card")) window.customCards.push({ type: "ki-bursdag-pro-card", name: "KI Bursdag Pro", description: "Bursdager i kalenderkort-stil", preview: true });
} catch (e) { console.error("ki-cards: 63-ki-bursdag-pro-card feilet", e); }

